def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for basic regex matching 
    that supports literal characters, '.', '*', and '+'.
    """

    def backtrack(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern):
            return t_idx == len(text)

        if p_idx + 1 < len(pattern) and pattern[p_idx + 1] in '*+':
            if pattern[p_idx + 1] == '*':
                # Try to match zero or more of the preceding element
                while t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
                    if backtrack(p_idx + 2, t_idx):
                        return True
                    t_idx += 1
                return backtrack(p_idx + 2, t_idx)  # Try without using *
            elif pattern[p_idx + 1] == '+':
                # At least one match for the preceding element
                if t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
                    if backtrack(p_idx + 2, t_idx + 1):
                        return True
                    t_idx += 1
                    while t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
                        if backtrack(p_idx + 2, t_idx):
                            return True
                        t_idx += 1
                return False

        if t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
            return backtrack(p_idx + 1, t_idx + 1)

        return False

    return backtrack(0, 0)

