    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements an iterative approach to regex matching using a stack 
    to handle characters, '.' (any character), '*' (zero or more), 
    and '+' (one or more) without recursion.
    """

    stack = [(0, 0)]
    while stack:
        p_idx, t_idx = stack.pop()

        if p_idx == len(pattern):
            if t_idx == len(text):
                return True
            continue

        if p_idx + 1 < len(pattern) and pattern[p_idx + 1] in '*+':
            if pattern[p_idx + 1] == '*':
                # Try to match zero or more of the preceding element
                stack.append((p_idx + 2, t_idx))  # Zero occurrence
                if t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
                    stack.append((p_idx, t_idx + 1))  # One occurrence
            elif pattern[p_idx + 1] == '+':
                # One or more of the preceding element
                if t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
                    stack.append((p_idx + 2, t_idx + 1))  # Match one occurrence first
                    stack.append((p_idx, t_idx + 1))      # Then try to match subsequent occurrences

        elif t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
            stack.append((p_idx + 1, t_idx + 1))  # Move both indices

    return False

