                    return True
                while t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.'):
                    if matches(p_idx + 2, t_idx + 1):
                        return True
                    t_idx += 1
                return False
            elif p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '+':
