                    if matches(p_idx + 2, t_idx + 1):
                        return True
                    t_idx += 1
                return False
            else:
                return False

        # Check for remaining '*' or '+' in pattern
        while p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
            p_idx += 2

        return p_idx == len(pattern) and t_idx == len(text)

    return matches(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a finite state machine (FSM) approach for basic regex matching 
    that supports literal characters, '.', '*', and '+'.
    """

    def build_fsm(pattern: str):
        fsm = {}
        m = len(pattern)
        state = 0

        for i in range(m):
            char = pattern[i]
            if char == '*':
                continue
            if char == '+':
                state = state - 1  # Adjust to reprocess the last state
                fsm[state] = fsm.get(state, []) + [(state, char)]
                continue

            fsm[state] = fsm.get(state, []) + [(state + 1, char)]
            if i + 1 < m and pattern[i + 1] == '*':
                fsm[state].append((state, char))  # State can stay if '*'
                state += 1  # Move to the next state

            if i + 1 < m and pattern[i + 1] == '+':
                fsm[state].append((state + 1, char))  # Can move to next state

            state += 1

        return fsm

    fsm = build_fsm(pattern)
    state = 0
    n = len(text)

    for char in text:
        next_state = state
        for transition in fsm.get(state, []):
            target_state, match_char = transition
            if (match_char == '.' or char == match_char):
                next_state = target_state
                break
        if next_state == state:
            return False  # No valid transition found
        state = next_state

    return state == len(pattern)
